starter.css:
/* Base link style from the prototype */
#schedule article a {
  color: #1d4ed8;
  text-decoration: underline;
}

/* Button component: leave this rule as it is */
.btn {
  display: inline-block;
  padding: 0.4em 0.9em;
  border-radius: 999px;
  color: #ffffff;
  background: #6d28d9;
  text-decoration: none;
}

